// 回滚要一次拿到三件事：目标版本的内容元数据、作品的归属与生命周期、目标版本本身还能不能用。
// 擦除过的版本不能作为回滚目标——它的内容列已经清空了，回滚过去等于产出一个空版本。
func (q *Queries) GetDemoForRestore(ctx context.Context, arg GetDemoForRestoreParams) (GetDemoForRestoreRow, error) {
	row := q.db.QueryRow(ctx, getDemoForRestore, arg.Slug, arg.RevNo)
	var i GetDemoForRestoreRow
	err := row.Scan(
		&i.DemoID,
		&i.Slug,
		&i.AuthorID,
		&i.LifecycleState,
		&i.ModerationState,
		&i.DeletedAt,
		&i.ErasedAt,
		&i.CurrentRevisionID,
		&i.RevisionID,
		&i.RevNo,
		&i.Title,
		&i.Description,
		&i.DemoType,
		&i.EntryPath,
		&i.SingleFile,
		&i.ManifestHash,
		&i.FileCount,
		&i.TotalBytes,
		&i.RevisionDeletedAt,
		&i.RevisionErasedAt,
	)
	return i, err
}

const getDemoGcWindow = `-- name: GetDemoGcWindow :one
SELECT q.purge_after, q.purged_at, q.abandoned_at
FROM gc_queue q
WHERE q.kind = 'demo_dir' AND q.object_key = $1::text
ORDER BY q.id DESC
LIMIT 1
`

type GetDemoGcWindowRow struct {
	PurgeAfter  pgtype.Timestamptz
	PurgedAt    pgtype.Timestamptz
	AbandonedAt pgtype.Timestamptz
}

// 恢复窗口的唯一判据：这条作品入队时算出的 purge_after（不是「当前配置的窗口」重算）。
// 读不到行 = 没入过队 = 没有窗口可判，调用方按「不可恢复」处理。
func (q *Queries) GetDemoGcWindow(ctx context.Context, objectKey string) (GetDemoGcWindowRow, error) {
	row := q.db.QueryRow(ctx, getDemoGcWindow, objectKey)
	var i GetDemoGcWindowRow
	err := row.Scan(&i.PurgeAfter, &i.PurgedAt, &i.AbandonedAt)
	return i, err
}

const listDemoRevisions = `-- name: ListDemoRevisions :many

SELECT r.rev_no,
       COALESCE(r.title, '')::text        AS title,
       r.demo_type,
       r.source,
       COALESCE(r.file_count, 0)::bigint  AS file_count,
       COALESCE(r.total_bytes, 0)::bigint AS total_bytes,
       r.created_at,
       (r.deleted_at IS NOT NULL)::bool   AS deleted,
       (r.erased_at IS NOT NULL)::bool    AS erased,
       -- 必须包 COALESCE：` + "`" + `r.id = NULL` + "`" + ` 的结果是 NULL 而不是 false，
       -- 扫进 Go 的 bool 会直接报 ` + "`" + `cannot scan NULL into *bool` + "`" + `。
       COALESCE(r.id = d.current_revision_id, false)::bool   AS is_current,
       COALESCE(r.id = d.published_revision_id, false)::bool AS is_published
FROM demo_revisions r
JOIN demos d ON d.id = r.demo_id
WHERE d.slug = $1
ORDER BY r.rev_no DESC
`

type ListDemoRevisionsRow struct {
	RevNo       int32
	Title       string
	DemoType    string
	Source      string
	FileCount   int64
	TotalBytes  int64
	CreatedAt   pgtype.Timestamptz
	Deleted     bool
	Erased      bool
	IsCurrent   bool
	IsPublished bool
}

// ===== 版本历史与回滚（设计 §7.3）=====
// 作者看自己的、审核员看任意作品。授权不在 SQL 里做（数据库不知道该是谁在调用），
// 这里只负责「按作品把所有版本列出来」。
//
// `is_current` / `is_published` 用两个指针直接比，不在应用层再推一遍：
// 这两个布尔就是「作者在改哪一版」「访客在看哪一版」的唯一事实源。
func (q *Queries) ListDemoRevisions(ctx context.Context, slug string) ([]ListDemoRevisionsRow, error) {
	rows, err := q.db.Query(ctx, listDemoRevisions, slug)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListDemoRevisionsRow{}
	for rows.Next() {
		var i ListDemoRevisionsRow
		if err := rows.Scan(
			&i.RevNo,
			&i.Title,
			&i.DemoType,
			&i.Source,
			&i.FileCount,
			&i.TotalBytes,
			&i.CreatedAt,
			&i.Deleted,
			&i.Erased,
			&i.IsCurrent,
			&i.IsPublished,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listPublishedDemos = `-- name: ListPublishedDemos :many

SELECT d.id, d.slug, d.title, d.cover_url, d.created_at,
       CASE
           WHEN $3::text = '' THEN 'title'
           WHEN d.title ILIKE '%' || $3::text || '%' THEN 'title'
           ELSE 'description'
       END::text AS matched_in
FROM demos d
WHERE d.published_revision_id IS NOT NULL
  AND d.lifecycle_state = 'published'
  AND d.deleted_at IS NULL
  AND d.erased_at IS NULL
  -- 渠道可见性：unlisted（可直链、不上列表）与 hidden（对外不可见）都必须生效，
  -- 否则发布时选的 visibility 就是个摆设。
  AND EXISTS (
      SELECT 1 FROM demo_channels c
      WHERE c.demo_id = d.id AND c.visibility = 'listed'
  )
  AND (
      $3::text = ''
      OR d.title ILIKE '%' || $3::text || '%'
      OR COALESCE(d.description, '') ILIKE '%' || $3::text || '%'
  )
ORDER BY d.created_at DESC, d.id DESC
LIMIT $1 OFFSET $2
`

type ListPublishedDemosParams struct {
	Limit  int32
	Offset int32
	Q      string
}

type ListPublishedDemosRow struct {
	ID        int64
	Slug      string
	Title     pgtype.Text
	CoverUrl  pgtype.Text
	CreatedAt pgtype.Timestamptz
	MatchedIn string
}

// 作品列表与详情。
//
// 「公开可见」的判定口径（列表、详情、预览、下载四处必须一致，改一处就要改其余三处）：
//
//	published_revision_id IS NOT NULL —— 有对外版本。**不再看审核态**：
//	                                  审核态描述的是「当前版本」，一件已发布作品在
//	                                  复审期间审核态是 pending，但对外内容仍在服务
//	                                  （迁移 0014 的版本分离，理由见那个文件头）
//	lifecycle_state = 'published'   —— 已发布，见标准对象 §ST-2 的可见性档位
//	deleted_at IS NULL              —— 没被删除
//	erased_at IS NULL               —— 没被擦除（擦除是逻辑封存，行还在但对外不存在）
//	至少一条 visibility='listed' 的渠道行 —— unlisted / hidden 必须真的不出现
//
// 已经归档（archived）或移除（removed）的作品**不在列表里**，但详情页仍可访问（墓碑），
// 所以这里查询条件与 GetDemoBySlug 故意不同——这不是漏写。
// `q` 是关键词：空串表示不过滤。匹配标题或简介（契约写的就是这两处）。
//
// 用 ILIKE 而不是全文检索，是刻意的：中文没有空格，pg_trgm 把两字的词
// （「探针」「回滚」）切不出完整三元组，索引用不上，最后还是回退成扫描。
// 那不如直接子串匹配——它至少**搜得到**。「搜得快」等数据量真的需要时再谈。
//
// `matched_in` 告诉前端这条是因为标题命中还是简介命中：只匹配简介时，
// 结果列表上看到的标题里没有关键词，不标出来就像「搜了但不相关」。
func (q *Queries) ListPublishedDemos(ctx context.Context, arg ListPublishedDemosParams) ([]ListPublishedDemosRow, error) {
	rows, err := q.db.Query(ctx, listPublishedDemos, arg.Limit, arg.Offset, arg.Q)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListPublishedDemosRow{}
	for rows.Next() {
		var i ListPublishedDemosRow
		if err := rows.Scan(
			&i.ID,
			&i.Slug,
			&i.Title,
			&i.CoverUrl,
			&i.CreatedAt,
			&i.MatchedIn,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const nextRevisionNo = `-- name: NextRevisionNo :one
SELECT (COALESCE(MAX(rev_no), 0) + 1)::int AS rev_no
FROM demo_revisions
WHERE demo_id = $1
`

// 版本号由数据库算，不由应用层「读最大值再加一」：并发的两次更新会读到同一个最大值，
// 然后一个撞唯一索引、另一个成功——撞的那个白做了一次上传。
func (q *Queries) NextRevisionNo(ctx context.Context, demoID int64) (int32, error) {
	row := q.db.QueryRow(ctx, nextRevisionNo, demoID)
	var rev_no int32
	err := row.Scan(&rev_no)
	return rev_no, err
}

const recordDemoView = `-- name: RecordDemoView :one

INSERT INTO demo_views (demo_id, viewer_key, viewed_on)
SELECT d.id, $1::text, current_date
FROM demos d
WHERE d.slug = $2::text
  AND d.lifecycle_state = 'published'
  AND d.published_revision_id IS NOT NULL
  AND d.deleted_at IS NULL
  AND d.erased_at IS NULL
ON CONFLICT (demo_id, viewer_key, viewed_on) DO NOTHING
RETURNING demo_id
`

type RecordDemoViewParams struct {
	ViewerKey string
	Slug      string
}

// ===== 浏览计数（DEMO-041）=====
// 一次浏览能不能算，全在这一条里判完：
//  1. 作品得是对外可读的（有对外版本、已发布、未删未擦）——草稿不该有浏览量；
//  2. 同一个人同一个自然日只算一次（主键冲突就不插入，返回 0 行）。
//
// **故意不判渠道visible性**：浏览计的是「有人来看了」，不是「它出现在哪里」。
// 渠道是 hidden 的作品，访客的详情请求本来就会被详情端点挡成 404，
// 到不了这里；而能拿到 slug 的人直接 POST 也只是给自己的记录加一行，一天一次封顶。
//
// 只返回被插入那一行的 demo_id：冲突（今天已经看过）时没有行，
// 调用方据此决定要不要 +1。用 :one + ErrNoRows 而不是 :execrows，
// 是因为 +1 还要拿 demo_id，再查一次 slug 换 id 就多一次往返。
func (q *Queries) RecordDemoView(ctx context.Context, arg RecordDemoViewParams) (int64, error) {
	row := q.db.QueryRow(ctx, recordDemoView, arg.ViewerKey, arg.Slug)
	var demo_id int64
	err := row.Scan(&demo_id)
	return demo_id, err
}

const restoreDeletedDemo = `-- name: RestoreDeletedDemo :exec
UPDATE demos
SET deleted_at = NULL, delete_reason = '', updated_at = now()
WHERE id = $1 AND deleted_at IS NOT NULL AND erased_at IS NULL
`

// 恢复 = 清空 deleted_at。作品自动回到删除前的档位，不需要额外的「原状态」列。
func (q *Queries) RestoreDeletedDemo(ctx context.Context, id int64) error {
	_, err := q.db.Exec(ctx, restoreDeletedDemo, id)
	return err
}

const setCurrentRevision = `-- name: SetCurrentRevision :exec
UPDATE demos SET current_revision_id = $2, updated_at = now() WHERE id = $1
`

type SetCurrentRevisionParams struct {
	ID                int64
	CurrentRevisionID pgtype.Int8
}

func (q *Queries) SetCurrentRevision(ctx context.Context, arg SetCurrentRevisionParams) error {
	_, err := q.db.Exec(ctx, setCurrentRevision, arg.ID, arg.CurrentRevisionID)
	return err
}

const setCurrentRevisionForEdit = `-- name: SetCurrentRevisionForEdit :exec
UPDATE demos
SET current_revision_id = $2,
    moderation_state    = 'pending',
    updated_at          = now()
WHERE id = $1
`

type SetCurrentRevisionForEditParams struct {
	ID                int64
	CurrentRevisionID pgtype.Int8
}

// 追加版本后：当前版本指向新版，审核态回到 pending（复审），**对外版本不动**。
// 这是「改稿期间线上作品照常服务」的全部实现——没有它，作者一提交更新，
// 自己作品的新内容就绕过审核直接对外了。
func (q *Queries) SetCurrentRevisionForEdit(ctx context.Context, arg SetCurrentRevisionForEditParams) error {
	_, err := q.db.Exec(ctx, setCurrentRevisionForEdit, arg.ID, arg.CurrentRevisionID)
	return err
}

const softDeleteDemo = `-- name: SoftDeleteDemo :exec
UPDATE demos
SET deleted_at = now(), delete_reason = $2, updated_at = now()
WHERE id = $1 AND deleted_at IS NULL AND erased_at IS NULL
`

type SoftDeleteDemoParams struct {
	ID           int64
	DeleteReason string
}

// 软删只写删除标记层，lifecycle_state 一个字节不动（生命周期 §4.3）。
func (q *Queries) SoftDeleteDemo(ctx context.Context, arg SoftDeleteDemoParams) error {
	_, err := q.db.Exec(ctx, softDeleteDemo, arg.ID, arg.DeleteReason)
	return err
}

const transitionDemoLifecycle = `-- name: TransitionDemoLifecycle :execrows
UPDATE demos
SET lifecycle_state = $1::text, updated_at = now()
WHERE id = $2
  AND lifecycle_state = $3::text
  AND deleted_at IS NULL
  AND erased_at IS NULL
`

type TransitionDemoLifecycleParams struct {
	ToState   string
	DemoID    int64
	FromState string
}

// 生命周期只有这一个写入口：目标状态与前置状态都由调用方给，条件在同一句里。
//
// 为什么不拆成 ArchiveDemo / UnarchiveDemo 两条：那会让「哪些跃迁合法」变成
// 两个文件位置的事实，接「平台移除」「申诉恢复」时就是第三、第四份。
// 现在合法性由 WHERE 的 lifecycle_state = @from_state 表达，唯一；0 行 = 跃迁不合法。
func (q *Queries) TransitionDemoLifecycle(ctx context.Context, arg TransitionDemoLifecycleParams) (int64, error) {
	result, err := q.db.Exec(ctx, transitionDemoLifecycle, arg.ToState, arg.DemoID, arg.FromState)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
